import React from 'react';
import { Link } from 'react-router-dom';
import './ForumPage.css';

const ForumPage = () => {
    const categories = [
        {
            id: 1,
            name: "General Discussion",
            forums: [
                {
                    id: 1,
                    name: "Introductions",
                    description: "Introduce yourself to the community.",
                    subForums: [
                        { id: 11, name: "New Members" },
                        { id: 12, name: "Off-Topic" },
                    ],
                    lastThread: { title: "Welcome!", author: "Admin", date: "2024-08-29" },
                },
                {
                    id: 2,
                    name: "News",
                    description: "Stay updated with the latest news.",
                    subForums: [
                        { id: 21, name: "Announcements" },
                        { id: 22, name: "Community News" },
                    ],
                    lastThread: { title: "New Features!", author: "Mod", date: "2024-08-28" },
                },
            ],
        },
        // Autres catégories...
    ];

    return (
        <div className="forum-page">
            {categories.map((category) => (
                <div key={category.id} className="category">
                    <h2>{category.name}</h2>
                    {category.forums.map((forum) => (
                        <div key={forum.id} className="forum">
                            <h3>
                                <Link to={`/forum/${forum.id}`}>{forum.name}</Link>
                            </h3>
                            <p>{forum.description}</p>
                            <ul className="subforums">
                                {forum.subForums.map((subForum) => (
                                    <li key={subForum.id}>{subForum.name}</li>
                                ))}
                            </ul>
                            <div className="last-thread">
                                <p><strong>Last thread:</strong> {forum.lastThread.title}</p>
                                <p><em>by {forum.lastThread.author} on {forum.lastThread.date}</em></p>
                            </div>
                        </div>
                    ))}
                </div>
            ))}
        </div>
    );
};

export default ForumPage;
